// File: notification-client/src/components/DeliveryDetails.tsx

import React, { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import axios from "axios";

interface Delivery {
  _id: string;
  customerId: string;
  driverId?: string;
  address: string;
  status: string;
  location: {
    lat: number;
    lng: number;
  };
}

const API_BASE_URL = process.env.REACT_APP_API_URL || "http://localhost:5000";

export default function DeliveryDetails() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();

  const [delivery, setDelivery] = useState<Delivery | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    if (!id) {
      setError("❗ No delivery ID provided in URL.");
      setLoading(false);
      return;
    }

    axios
      .get(`${API_BASE_URL}/api/delivery/${id}`)
      .then((res) => {
        setDelivery(res.data);
        setLoading(false);
      })
      .catch((err) => {
        console.error("Error fetching delivery details:", err);
        setError("❌ Failed to fetch delivery details");
        setLoading(false);
      });
  }, [id]);

  if (loading) return <div>Loading...</div>;
  if (error || !delivery) return <div>{error || "Delivery not found"}</div>;

  const googleMapsLink = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(delivery.address)}`;

  const embeddedMapSrc = `https://www.google.com/maps?q=${encodeURIComponent(delivery.address)}&output=embed`;

  return (
    <div style={{ padding: "20px" }}>
      <h2>📦 Delivery Details</h2>

      <p><strong>Customer ID:</strong> {delivery.customerId}</p>
      <p><strong>Status:</strong> {delivery.status}</p>
      <p><strong>Driver ID:</strong> {delivery.driverId || "Not assigned"}</p>
      <p><strong>Delivery Address:</strong> {delivery.address}</p>

      <div style={{ marginTop: "20px", display: "flex", gap: "1rem" }}>
        <button
          onClick={() => navigate("/")}
          style={{
            padding: "10px 20px",
            backgroundColor: "#6c757d",
            color: "#fff",
            border: "none",
            borderRadius: "4px",
            cursor: "pointer",
          }}
        >
          ← Back to Dashboard
        </button>

        <a
          href={googleMapsLink}
          target="_blank"
          rel="noopener noreferrer"
          style={{ textDecoration: "none" }}
        >
          <button
            style={{
              padding: "10px 20px",
              backgroundColor: "#007bff",
              color: "#fff",
              border: "none",
              borderRadius: "4px",
              cursor: "pointer",
            }}
          >
            📍 Open in Google Maps
          </button>
        </a>
      </div>

      {/* Embedded Google Map */}
      <div style={{ marginTop: "30px" }}>
        <h3>🗺️ Delivery Location Map:</h3>
        <iframe
          title="Delivery Location"
          width="100%"
          height="400"
          frameBorder="0"
          style={{ border: 0 }}
          src={embeddedMapSrc}
          allowFullScreen
        />
      </div>
    </div>
  );
}
